 const income=sum(items,'income'),expense=sum(items,'expense'),net=income-expense,period=periodLabel(filter),company=getCompanyDetails(),companyName=company.name.trim()||'Syed Global Group PVT LTD',companyLogo=company.logo?'<img class="report-logo" src="'+esc(company.logo)+'" alt="Company logo">':'',companyLines=[company.address?'<div class="report-company-line">'+esc(company.address)+'</div>':'',company.phone?'<div class="report-company-line">Phone: '+esc(company.phone)+'</div>':'',company.email?'<div class="report-company-line">Email: '+esc(company.email)+'</div>':'',company.gstin?'<div class="report-company-line">GSTIN: '+esc(company.gstin)+'</div>':''].filter(Boolean).join('');
