function renderManageCategories(){for(const type of ['income','expense']){$(type==='income'?'manage-income':'manage-expense').innerHTML=categories(type).map(name=>`<div class="manage-row"><input class="manage-name" value="${esc(name)}" data-type="${type}" aria-label="${type} category name"><button class="btn secondary small" data-save-category="${type}" data-original="${esc(name)}">Save</button></div>`).join('')||'<div class="empty">No categories yet.</div>'}}
function addManagedCategory(type){const field=$(type==='income'?'new-income-category':'new-expense-category'),name=field.value.trim();if(!name)return toast('Enter a category name');if(categories(type).some(x=>x.toLowerCase()===name.toLowerCase()))return toast('That category already exists');customCats[type].push(name);localStorage.setItem(CAT_KEY,JSON.stringify(customCats));field.value='';renderManageCategories();renderDaily();setDatalist();toast('Category added')}
