function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2300)}function openModal(entry){$('entry-form').reset();$('entry-id').value=entry?.id||'';$('modal-title').textContent=entry?'Edit entry':'Add entry';$('entry-type').value=entry?.type||'income';$('entry-date').value=entry?.date||new Date().toISOString().slice(0,10);$('entry-category').value=entry?.category||'';$('entry-amount').value=entry?.amount??'';$('entry-note').value=entry?.note||'';$('modal').classList.add('open');setDatalist();setTimeout(()=>$('entry-category').focus(),50)}function closeModal(){$('modal').classList.remove('open')}
function save(e){e.preventDefault();const id=$('entry-id').value;const obj={id:id||`manual-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,type:$('entry-type').value,date:$('entry-date').value,category:$('entry-category').value.trim(),amount:Number($('entry-amount').value),note:$('entry-note').value.trim()};if(!obj.category||!obj.date||obj.amount<=0)return;records=id?records.map(x=>x.id===id?obj:x):[obj,...records];persist();closeModal();allPage=0;render();toast(id?'Entry updated':'Entry saved')}
